-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE customers(id); INSERT INTO customers VALUES(1),(2); CREATE TABLE orders(customer_id); INSERT INTO orders VALUES(1);
SELECT COUNT(*) FROM customers c JOIN orders o ON c.id=o.customer_id;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE orders(id, amount); INSERT INTO orders VALUES(1,1000),(2,3000),(3,5000);
SELECT COUNT(*) FROM orders WHERE amount >= 3000;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE orders(id, coupon); INSERT INTO orders VALUES(1,'WELCOME'),(2,NULL),(3,NULL);
SELECT COUNT(*) FROM orders WHERE coupon IS NULL;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE orders(id, amount); INSERT INTO orders VALUES(1,2000),(2,7000),(3,4000);
SELECT id FROM orders ORDER BY amount DESC LIMIT 1;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE orders(id, status); INSERT INTO orders VALUES(1,'done'),(2,'cancel'),(3,'ready'),(4,'done');
SELECT COUNT(*) FROM orders WHERE status IN ('done', 'ready');

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE users(id, tier); INSERT INTO users VALUES(1,'gold'),(2,'silver'),(3,NULL);
SELECT id FROM users WHERE COALESCE(tier, 'none') <> 'gold' ORDER BY id;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE customers(id); INSERT INTO customers VALUES(1),(2),(3); CREATE TABLE orders(customer_id); INSERT INTO orders VALUES(1);
SELECT COUNT(*) FROM customers c LEFT JOIN orders o ON c.id=o.customer_id;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE customers(id); INSERT INTO customers VALUES(1),(2); CREATE TABLE orders(id, customer_id); INSERT INTO orders VALUES(10,1),(11,1);
SELECT COUNT(*), COUNT(o.id) FROM customers c LEFT JOIN orders o ON c.id=o.customer_id WHERE c.id=2;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE sales(team, status, amount); INSERT INTO sales VALUES('A','done',4000),('A','cancel',5000),('A','done',3000),('B','done',6000);
SELECT team FROM sales WHERE status='done' GROUP BY team HAVING SUM(amount) >= 7000 ORDER BY team;
